     1→// 桐城自摸麻将 - 局域网服务器
     2→// 运行方式: node majiang-server.js
     3→
     4→const http = require('http');
     5→const fs = require('fs');
     6→const path = require('path');
     7→const WebSocket = require('ws');
     8→
     9→const PORT = 8082;
    10→
    11→// ==================== HTTP服务器 ====================
    12→const server = http.createServer((req, res) => {
    13→    console.log(`HTTP请求: ${req.url}`);
    14→
    15→    // 解码URL（处理中文文件名）
    16→    const decodedUrl = decodeURIComponent(req.url);
    17→
    18→    if (req.url === '/' || req.url === '/index.html') {
    19→        const htmlPath = path.join(__dirname, 'majiang-lan.html');
    20→        fs.readFile(htmlPath, (err, data) => {
    21→            if (err) {
    22→                res.writeHead(404);
    23→                res.end('游戏文件未找到');
    24→                return;
    25→            }
    26→            res.writeHead(200, {
    27→                'Content-Type': 'text/html; charset=utf-8'
    28→            });
    29→            res.end(data);
    30→        });
    31→    } else if (req.url === '/favicon.ico') {
    32→        res.writeHead(204);
    33→        res.end();
    34→    } else if (decodedUrl.endsWith('.jpg') || decodedUrl.endsWith('.jpeg') || decodedUrl.endsWith('.png') || decodedUrl.endsWith('.gif')) {
    35→        // 处理图片文件
    36→        const imagePath = path.join(__dirname, decodedUrl);
    37→        fs.readFile(imagePath, (err, data) => {
    38→            if (err) {
    39→                console.log(`图片未找到: ${imagePath}`);
    40→                res.writeHead(404);
    41→                res.end('图片未找到');
    42→                return;
    43→            }
    44→            const ext = path.extname(decodedUrl).toLowerCase();
    45→            const contentTypes = {
    46→                '.jpg': 'image/jpeg',
    47→                '.jpeg': 'image/jpeg',
    48→                '.png': 'image/png',
    49→                '.gif': 'image/gif'
    50→            };
    51→            res.writeHead(200, {
    52→                'Content-Type': contentTypes[ext] || 'application/octet-stream'
    53→            });
    54→            res.end(data);
    55→        });
    56→    } else {
    57→        res.writeHead(404);
    58→        res.end('Not Found');
    59→    }
    60→});
    61→
    62→// ==================== WebSocket服务器 ====================
    63→const wss = new WebSocket.Server({ server });
    64→
    65→// 游戏房间管理
    66→const tables = new Map();
    67→const playerToTable = new Map();
    68→let tableCounter = 0;
    69→
    70→// 所有已登录的客户端（用于广播牌桌列表）
    71→const loggedInClients = new Set();
    72→
    73→// ==================== 牌面常量 ====================
    74→const SUITS = ['筒', '条', '万'];
    75→const RANKS = [1, 2, 3, 4, 5, 6, 7, 8, 9];
    76→const WINDS = ['东', '南', '西', '北'];
    77→const ARROWS = ['中', '发', '白'];
    78→
    79→// 创建一副麻将牌
    80→function createDeck() {
    81→    const deck = [];
    82→
    83→    // 筒条万 (每种4张)
    84→    for (const suit of SUITS) {
    85→        for (const rank of RANKS) {
    86→            for (let i = 0; i < 4; i++) {
    87→                deck.push({
    88→                    suit,
    89→                    rank,
    90→                    type: 'number',
    91→                    id: `${suit}${rank}_${i}`
    92→                });
    93→            }
    94→        }
    95→    }
    96→
    97→    // 风牌 (每种4张)
    98→    for (const wind of WINDS) {
    99→        for (let i = 0; i < 4; i++) {
   100→            deck.push({
   101→                suit: '风',
   102→                rank: wind,
   103→                type: 'wind',
   104→                id: `风${wind}_${i}`
   105→            });
   106→        }
   107→    }
   108→
   109→    // 箭牌 (每种4张)
   110→    for (const arrow of ARROWS) {
   111→        for (let i = 0; i < 4; i++) {
   112→            deck.push({
   113→                suit: '箭',
   114→                rank: arrow,
   115→                type: 'arrow',
   116→                id: `箭${arrow}_${i}`
   117→            });
   118→        }
   119→    }
   120→
   121→    return deck; // 136张
   122→}
   123→
   124→// 洗牌
   125→function shuffle(deck) {
   126→    const shuffled = [...deck];
   127→    for (let i = shuffled.length - 1; i > 0; i--) {
   128→        const j = Math.floor(Math.random() * (i + 1));
   129→        [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
   130→    }
   131→    return shuffled;
   132→}
   133→
   134→// 牌的显示名称
   135→function cardName(card) {
   136→    if (card.type === 'number') {
   137→        return `${card.rank}${card.suit}`;
   138→    } else {
   139→        return card.rank;
   140→    }
   141→}
   142→
   143→// ==================== 牌桌类 ====================
   144→class GameTable {
   145→    constructor(id, tableNumber) {
   146→        this.id = id;
   147→        this.tableNumber = tableNumber;
   148→        this.players = new Map(); // playerId -> player info
   149→        this.spectators = new Map();
   150→        this.maxPlayers = 4;
   151→        this.gameTimer = null; // 游戏计时器
   152→
   153→        // 周期（头）相关属性
   154→        this.cycleStartTime = null; // 周期开始时间
   155→        this.cycleDuration = 60 * 60 * 1000; // 1小时（毫秒）
   156→
   157→        // 游戏流程相关属性
   158→        this.currentRound = 0; // 当前局数
   159→        this.lastWinner = null; // 上一局赢家 playerId
   160→        this.roundReadyPlayers = new Set(); // 每局结束后已准备的玩家
   161→
   162→        // 骰子状态
   163→        this.diceState = {
   164→            firstRoll: null, // 第一次骰子结果 { playerId, values: [d1, d2] }
   165→            secondRoll: null, // 第二次骰子结果 { playerId, values: [d1, d2] }
   166→            currentRoller: null, // 当前应该掷骰子的人
   167→            rollPhase: 0 // 0=未开始, 1=等待第一次, 2=等待第二次, 3=完成
   168→        };
   169→
   170→        this.gameState = {
   171→            started: false,
   172→            currentPlayer: 0, // 0-3, 当前出牌玩家索引
   173→            dealer: 0, // 庄家索引
   174→            dealerSeat: 1, // 庄家座位号（1-4）
   175→            deck: [], // 牌堆
   176→            hands: {}, // playerId -> cards[]
   177→            wildCard: null, // 万能牌
   178→            discardedPile: [], // 打出的牌
   179→            showedCards: {}, // playerId -> { fa: [], gang: [] }
   180→            faUsed: {}, // playerId -> 玩家是否已换过发
   181→            lastDrawn: null, // 最后摸的牌
   182→            gameStartTime: null, // 游戏开始时间
   183→            totalGameTime: 0, // 游戏总时长（秒）
   184→            roundPhase: 'waiting' // waiting=等待准备, dice=掷骰子阶段, playing=游戏中, ended=本局结束
   185→        };
   186→    }
   187→
   188→    // 获取按座位排序的玩家ID数组
   189→    getSortedPlayerIds() {
   190→        return Array.from(this.players.entries())
   191→            .sort((a, b) => a[1].seatNum - b[1].seatNum)
   192→            .map(([id]) => id);
   193→    }
   194→
   195→    // 添加玩家
   196→    addPlayer(ws, playerId, playerName, seatNum = null) {
   197→        if (this.players.size >= this.maxPlayers) return false;
   198→        if (this.gameState.started) return false;
   199→
   200→        let actualSeat;
   201→        if (seatNum !== null && seatNum >= 1 && seatNum <= 4) {
   202→            const occupied = Array.from(this.players.values()).some(p => p.seatNum === seatNum);
   203→            if (occupied) return false;
   204→            actualSeat = seatNum;
   205→        } else {
   206→            const occupiedSeats = new Set(Array.from(this.players.values()).map(p => p.seatNum));
   207→            for (let i = 1; i <= 4; i++) {
   208→                if (!occupiedSeats.has(i)) {
   209→                    actualSeat = i;
   210→                    break;
   211→                }
   212→            }
   213→        }
   214→
   215→        this.players.set(playerId, {
   216→            ws,
   217→            id: playerId,
   218→            name: playerName,
   219→            seatNum: actualSeat,
   220→            ready: false,
   221→            isAI: false
   222→        });
   223→
   224→        return true;
   225→    }
   226→
   227→    // 移除玩家
   228→    removePlayer(playerId) {
   229→        this.players.delete(playerId);
   230→        return this.players.size === 0;
   231→    }
   232→
   233→    // 检查是否所有玩家都已断开连接
   234→    isAllPlayersDisconnected() {
   235→        if (this.players.size === 0) return true;
   236→        for (const player of this.players.values()) {
   237→            if (player.ws && player.ws.readyState === WebSocket.OPEN) {
   238→                return false;
   239→            }
   240→        }
   241→        return true;
   242→    }
   243→
   244→    // 设置准备状态
   245→    setPlayerReady(playerId, ready) {
   246→        const player = this.players.get(playerId);
   247→        if (player) {
   248→            player.ready = ready;
   249→            this.broadcastPlayerList();
   250→            this.checkStartGame();
   251→        }
   252→    }
   253→
   254→    // 检查是否可以开始游戏
   255→    checkStartGame() {
   256→        const allReady = Array.from(this.players.values()).every(p => p.ready);
   257→        const humanCount = Array.from(this.players.values()).filter(p => !p.isAI).length;
   258→
   259→        console.log(`checkStartGame: allReady=${allReady}, players=${this.players.size}, humans=${humanCount}, roundPhase=${this.gameState.roundPhase}`);
   260→
   261→        if (this.gameState.roundPhase === 'waiting' || !this.gameState.started) {
   262→            // 新游戏或新一周期的开始
   263→            // 需要4个玩家（至少1个真人），且所有人都准备好
   264→            if (allReady && this.players.size >= 4 && humanCount >= 1) {
   265→                // 检查是否是新周期
   266→                if (!this.cycleStartTime || (Date.now() - this.cycleStartTime >= this.cycleDuration)) {
   267→                    this.cycleStartTime = Date.now();
   268→                    this.currentRound = 0;
   269→                    console.log(`牌桌${this.tableNumber} 开始新周期`);
   270→                }
   271→                console.log(`牌桌${this.tableNumber} 所有人已准备，开始掷骰子阶段`);
   272→                this.startDicePhase();
   273→            }
   274→        } else if (this.gameState.roundPhase === 'ended') {
   275→            // 局间准备，检查所有人是否都准备了
   276→            const allRoundReady = this.roundReadyPlayers.size === this.players.size;
   277→            if (allRoundReady) {
   278→                this.startDicePhase();
   279→            }
   280→        }
   281→    }
   282→
   283→    // 开始掷骰子阶段
   284→    startDicePhase() {
   285→        // 先初始化牌堆和庄家
   286→        this.initDeckAndDealer();
   287→
   288→        this.gameState.roundPhase = 'dice';
   289→        this.diceState = {
   290→            firstRoll: null,
   291→            secondRoll: null,
   292→            currentRoller: null,
   293→            rollPhase: 1
   294→        };
   295→
   296→        // 确定第一次掷骰子的人
   297→        const firstRollerId = this.getFirstRoller();
   298→        const firstRoller = this.players.get(firstRollerId);
   299→        this.diceState.currentRoller = firstRollerId;
   300→
   301→        this.broadcastMessage(`🎲 第${this.currentRound + 1}局开始！请 ${firstRoller.name} 掷骰子`);
   302→
   303→        // 通知所有人骰子状态
   304→        this.broadcastDiceState();
   305→
   306→        // 检查是否轮到AI掷骰子
   307→        setTimeout(() => this.checkAITurn(), 500);
   308→    }
   309→
   310→    // 获取第一次掷骰子的人
   311→    getFirstRoller() {
   312→        const playerIds = this.getSortedPlayerIds();
   313→
   314→        if (this.currentRound === 0) {
   315→            // 周期第一局：座东的玩家坐庄并先掷骰子
   316→            // 座位与方位对应：1号位=南，2号位=东，3号位=西，4号位=北
   317→            const dongPlayer = Array.from(this.players.values()).find(p => p.seatNum === 2);
   318→            if (dongPlayer) {
   319→                this.gameState.dealerSeat = 2;
   320→                this.gameState.dealer = playerIds.indexOf(dongPlayer.id);
   321→                return dongPlayer.id;
   322→            }
   323→        } else {
   324→            // 后续局：上一局胡牌者掷第一次骰子
   325→            if (this.lastWinner) {
   326→                // 上局赢家成为庄家
   327→                const winner = this.players.get(this.lastWinner);
   328→                if (winner) {
   329→                    this.gameState.dealerSeat = winner.seatNum;
   330→                    this.gameState.dealer = playerIds.indexOf(this.lastWinner);
   331→                }
   332→                return this.lastWinner;
   333→            }
   334→        }
   335→
   336→        // 默认返回第一个玩家
   337→        return playerIds[0];
   338→    }
   339→
   340→    // 获取第二次掷骰子的人（根据第一次骰子点数和，逆时针数）
   341→    getSecondRoller(firstSum) {
   342→        const playerIds = this.getSortedPlayerIds();
   343→        const firstRollerIndex = playerIds.indexOf(this.diceState.firstRoll.playerId);
   344→
   345→        // playerIds 是 [座位1, 座位2, 座位3, 座位4]（顺时针：东→南→西→北）
   346→        // 逆时针顺序：东(0)→北(3)→西(2)→南(1)→东(0)
   347→        // 逆时针移动一步 = 索引 -1（或 +3 mod 4）
   348→        // 数firstSum步，从1开始数（所以-1）
   349→        const secondRollerIndex = (firstRollerIndex - (firstSum - 1) % 4 + 4) % 4;
   350→        return playerIds[secondRollerIndex];
   351→    }
   352→
   353→    // 掷骰子
   354→    rollDice(playerId, values) {
   355→        console.log(`rollDice 被调用: playerId=${playerId}, values=${JSON.stringify(values)}, currentRoller=${this.diceState.currentRoller}, rollPhase=${this.diceState.rollPhase}`);
   356→
   357→        if (this.diceState.currentRoller !== playerId) {
   358→            console.log(`不是你的回合掷骰子: currentRoller=${this.diceState.currentRoller}, playerId=${playerId}`);
   359→            return { success: false, message: '不是你的回合掷骰子' };
   360→        }
   361→
   362→        const player = this.players.get(playerId);
   363→        if (!player) {
   364→            console.log(`找不到玩家: ${playerId}`);
   365→            return { success: false, message: '玩家不存在' };
   366→        }
   367→
   368→        if (this.diceState.rollPhase === 1) {
   369→            // 第一次掷骰子
   370→            console.log(`第一次掷骰子: ${player.name}`);
   371→            this.diceState.firstRoll = { playerId, playerName: player.name, values };
   372→            this.diceState.rollPhase = 2;
   373→
   374→            // 根据第一次骰子点数和，确定第二次掷骰子的人
   375→            const firstSum = values[0] + values[1];
   376→            console.log(`计算第二次掷骰者: firstSum=${firstSum}`);
   377→            const secondRollerId = this.getSecondRoller(firstSum);
   378→            console.log(`第二次掷骰者ID: ${secondRollerId}`);
   379→
   380→            if (!secondRollerId) {
   381→                console.error(`无法确定第二次掷骰者!`);
   382→                return { success: false, message: '无法确定第二次掷骰者' };
   383→            }
   384→
   385→            this.diceState.currentRoller = secondRollerId;
   386→            const secondRoller = this.players.get(secondRollerId);
   387→
   388→            if (!secondRoller) {
   389→                console.error(`找不到第二次掷骰者: ${secondRollerId}`);
   390→                return { success: false, message: '找不到第二次掷骰者' };
   391→            }
   392→
   393→            this.broadcastMessage(`🎲 ${player.name} 掷出 ${values[0]}+${values[1]}=${firstSum} 点`);
   394→            this.broadcastMessage(`🎲 从${player.name}逆时针数${firstSum}步，请 ${secondRoller.name} 掷第二次骰子`);
   395→
   396→            this.broadcastDiceState();
   397→
   398→            // 检查是否轮到AI掷第二次骰子
   399→            setTimeout(() => this.checkAITurn(), 500);
   400→
   401→            return { success: true, phase: 1, values };
   402→
   403→        } else if (this.diceState.rollPhase === 2) {
   404→            // 第二次掷骰子
   405→            this.diceState.secondRoll = { playerId, playerName: player.name, values };
   406→            this.diceState.rollPhase = 3;
   407→
   408→            this.broadcastMessage(`🎲 ${player.name} 掷出 ${values[0]}+${values[1]}=${values[0]+values[1]} 点`);
   409→
   410→            // 确定抓牌位置和癞子
   411→            this.determineWildCard();
   412→
   413→            // 开始发牌
   414→            setTimeout(() => {
   415→                this.startDealCards();
   416→            }, 1000);
   417→
   418→            this.broadcastDiceState();
   419→
   420→            return { success: true, phase: 2, values };
   421→        }
   422→
   423→        return { success: false, message: '骰子阶段错误' };
   424→    }
   425→
   426→    // 根据亮牌确定癞子（下一张牌）
   427→    getWildCardFromShown(shownCard) {
   428→        // 普通牌（筒条万）：1-9循环
   429→        if (shownCard.type === 'number') {
   430→            const nextRank = shownCard.rank >= 9 ? 1 : shownCard.rank + 1;
   431→            return {
   432→                suit: shownCard.suit,
   433→                rank: nextRank,
   434→                type: 'number'
   435→            };
   436→        }
   437→        // 风牌：东南西北循环
   438→        if (shownCard.type === 'wind') {
   439→            const windOrder = ['东', '南', '西', '北'];
   440→            const currentIndex = windOrder.indexOf(shownCard.rank);
   441→            const nextIndex = (currentIndex + 1) % 4;
   442→            return {
   443→                suit: '风',
   444→                rank: windOrder[nextIndex],
   445→                type: 'wind'
   446→            };
   447→        }
   448→        // 箭牌：中发白循环
   449→        if (shownCard.type === 'arrow') {
   450→            const arrowOrder = ['中', '发', '白'];
   451→            const currentIndex = arrowOrder.indexOf(shownCard.rank);
   452→            const nextIndex = (currentIndex + 1) % 3;
   453→            return {
   454→                suit: '箭',
   455→                rank: arrowOrder[nextIndex],
   456→                type: 'arrow'
   457→            };
   458→        }
   459→        return null;
   460→    }
   461→
   462→    // 确定万能牌（癞子）和抓牌位置 - 根据骰子结果
   463→    determineWildCard() {
   464→        const firstSum = this.diceState.firstRoll.values[0] + this.diceState.firstRoll.values[1];
   465→        const secondSum = this.diceState.secondRoll.values[0] + this.diceState.secondRoll.values[1];
   466→        const total = firstSum + secondSum;
   467→
   468→        console.log(`第1次骰子: ${firstSum}, 第2次骰子: ${secondSum}, 总计: ${total}`);
   469→
   470→        // 牌墙布局：每个玩家面前17墩牌（每墩2张），按逆时针排列
   471→        // 座位1(东) -> 座位4(北) -> 座位3(西) -> 座位2(南) -> 座位1(东)
   472→        // 牌墙索引：0-33(东), 34-67(北), 68-101(西), 102-135(南)
   473→        // 每个方位17墩，每墩2张牌
   474→
   475→        const firstRollerSeat = this.players.get(this.diceState.firstRoll.playerId)?.seatNum || 1;
   476→
   477→        // 根据第一次骰子确定从哪个方位开始数
   478→        // 逆时针方向：东(1) -> 北(4) -> 西(3) -> 南(2) -> 东(1)
   479→        const seatToDirection = { 1: '东', 2: '南', 3: '西', 4: '北' };
   480→        const directionOrder = [1, 4, 3, 2]; // 逆时针顺序
   481→
   482→        // 第1次骰子点数决定从哪个方位开始（从掷骰者的方位开始数）
   483→        const startDirectionIndex = directionOrder.indexOf(firstRollerSeat);
   484→        const countDirection = (startDirectionIndex + firstSum - 1) % 4;
   485→        const startDirection = directionOrder[countDirection];
   486→
   487→        console.log(`开始方位: ${seatToDirection[startDirection]} (座位${startDirection})`);
   488→
   489→        // 计算从开始方位最左边数起，数total墩
   490→        // 每个方位17墩
   491→        const pilesPerDirection = 17;
   492→        let remainingPiles = total;
   493→        let currentDirection = startDirection;
   494→        let directionIdx = directionOrder.indexOf(currentDirection);
   495→
   496→        // 数牌墩
   497→        while (remainingPiles > pilesPerDirection) {
   498→            remainingPiles -= pilesPerDirection;
   499→            directionIdx = (directionIdx + 1) % 4;
   500→            currentDirection = directionOrder[directionIdx];
   501→        }
   502→
   503→        // 确定抓牌起始位置
   504→        // 抓牌从第remainingPiles墩的下一墩开始
   505→        const drawPile = remainingPiles; // 第几墩（1-17）
