   603→        this.gameState.discardedPile = [];
   604→        this.gameState.showedCards = {};
   605→        this.gameState.faUsed = {};
   606→        this.gameState.lastDrawn = null;
   607→
   608→        // 初始化手牌
   609→        const playerIds = this.getSortedPlayerIds();
   610→        for (const pid of playerIds) {
   611→            this.gameState.hands[pid] = [];
   612→            this.gameState.showedCards[pid] = { fa: [], gang: [] };
   613→            this.gameState.faUsed[pid] = false;
   614→        }
   615→
   616→        // 根据 drawInfo 计算抓牌起始位置
   617→        const drawInfo = this.gameState.drawInfo;
   618→        if (drawInfo && drawInfo.drawDirection) {
   619→            // 方位到数组偏移的映射（牌墙按 东17墩 北17墩 西17墩 南17墩 排列）
   620→            const directionToOffset = { 1: 0, 4: 17, 3: 34, 2: 51 };
   621→            // 每墩2张牌，计算起始索引（从drawDirection方位的第drawPile墩后开始）
   622→            // drawPile 表示"第几墩后开始"，所以实际起始是第 drawPile+1 墩
   623→            let startIndex = (directionToOffset[drawInfo.drawDirection] + drawInfo.drawPile) * 2;
   624→            // 确保索引在有效范围内
   625→            startIndex = Math.max(0, Math.min(startIndex, this.gameState.deck.length - 1));
   626→
   627→            // 重排牌堆，使抓牌位置成为新的牌顶
   628→            if (startIndex > 0) {
   629→                const before = this.gameState.deck.slice(0, startIndex);
   630→                const after = this.gameState.deck.slice(startIndex);
   631→                this.gameState.deck = [...after, ...before];
   632→                console.log(`牌堆重排：从${drawInfo.drawDirection}方第${drawInfo.drawPile}墩后（索引${startIndex}）开始，剩余${this.gameState.deck.length}张`);
   633→            }
   634→        }
   635→
   636→        // 初始化牌墙状态：每个方位17墩
   637→        this.gameState.wallState = { 1: 17, 2: 17, 3: 17, 4: 17 };
   638→
   639→        // 逆时针顺序：东(1)→北(4)→西(3)→南(2)
   640→        // playerIds 是 [座位1, 座位2, 座位3, 座位4]（顺时针）
   641→        // 逆时针需要调整为 [座位1, 座位4, 座位3, 座位2]
   642→        const counterClockwiseIds = [
   643→            playerIds[0], // 座位1(东)
   644→            playerIds[3], // 座位4(北)
   645→            playerIds[2], // 座位3(西)
   646→            playerIds[1]  // 座位2(南)
   647→        ];
   648→
   649→        // 发牌：每人4张×3轮，然后每人1张，庄家多1张
   650→        // 每人4张×3轮（逆时针顺序）- 相当于每人2墩×3轮
   651→        for (let round = 0; round < 3; round++) {
   652→            for (const pid of counterClockwiseIds) {
   653→                for (let i = 0; i < 4; i++) {
   654→                    const card = this.gameState.deck.pop();
   655→                    if (card) this.gameState.hands[pid].push(card);
   656→                }
   657→            }
   658→        }
   659→
   660→        // 每人1张（逆时针顺序）
   661→        for (const pid of counterClockwiseIds) {
   662→            const card = this.gameState.deck.pop();
   663→            if (card) this.gameState.hands[pid].push(card);
   664→        }
   665→
   666→        // 庄家多拿1张
   667→        const dealerPid = playerIds[this.gameState.dealer];
   668→        const extraCard = this.gameState.deck.pop();
   669→        if (extraCard) this.gameState.hands[dealerPid].push(extraCard);
   670→
   671→        // 更新牌墙状态（根据实际抓取的牌数）
   672→        this.updateWallState();
   673→
   674→        // 庄家先出牌
   675→        this.gameState.currentPlayer = this.gameState.dealer;
   676→
   677→        // 排序手牌
   678→        for (const pid of playerIds) {
   679→            this.sortHand(pid);
   680→        }
   681→
   682→        console.log(`牌桌${this.tableNumber} 第${this.currentRound}局开始，庄家座位: ${this.gameState.dealerSeat}，万能牌: ${cardName(this.gameState.wildCard)}`);
   683→        console.log(`发牌完成，牌堆剩余: ${this.gameState.deck.length}张，牌墙状态: ${JSON.stringify(this.gameState.wallState)}`);
   684→
   685→        // 直接发送游戏状态（删除发牌动画）
   686→        this.broadcastGameState();
   687→        // 检查是否轮到AI出牌
   688→        this.checkAITurn();
