   824→    // 排序手牌
   825→    sortHand(playerId) {
   826→        const hand = this.gameState.hands[playerId];
   827→        if (!hand) return;
   828→
   829→        const suitOrder = { '筒': 0, '条': 1, '万': 2, '风': 3, '箭': 4 };
   830→        const windOrder = { '东': 0, '南': 1, '西': 2, '北': 3 };
   831→        const arrowOrder = { '中': 0, '发': 1, '白': 2 };
   832→
   833→        hand.sort((a, b) => {
   834→            // 万能牌放最后
   835→            if (this.isWildCard(a) && !this.isWildCard(b)) return 1;
   836→            if (!this.isWildCard(a) && this.isWildCard(b)) return -1;
   837→
   838→            const suitA = suitOrder[a.suit] ?? 5;
   839→            const suitB = suitOrder[b.suit] ?? 5;
   840→            if (suitA !== suitB) return suitA - suitB;
   841→
   842→            if (a.type === 'number' && b.type === 'number') {
   843→                return a.rank - b.rank;
   844→            } else if (a.type === 'wind' && b.type === 'wind') {
   845→                return (windOrder[a.rank] ?? 0) - (windOrder[b.rank] ?? 0);
   846→            } else if (a.type === 'arrow' && b.type === 'arrow') {
   847→                return (arrowOrder[a.rank] ?? 0) - (arrowOrder[b.rank] ?? 0);
   848→            }
   849→            return 0;
   850→        });
   851→    }
