   853→    // 判断是否是万能牌（相同牌或红中）
   854→    isWildCard(card) {
   855→        const wild = this.gameState.wildCard;
   856→        if (!wild) return false;
   857→
   858→        // 相同牌是万能牌
   859→        if (card.suit === wild.suit && card.rank === wild.rank) return true;
   860→        // 红中也是万能牌
   861→        if (card.type === 'arrow' && card.rank === '中') return true;
   862→
   863→        return false;
   864→    }
