   884→    // 更新牌墙状态
   885→    updateWallState() {
   886→        // 计算已抓取的牌数（初始136张，减去亮牌1张，减去牌堆剩余）
   887→        const initialCards = 136 - 1; // 总牌数减去亮牌
   888→        const remainingCards = this.gameState.deck.length;
   889→        const drawnCards = initialCards - remainingCards;
   890→
   891→        // 牌墙初始状态：每个方位17墩
   892→        // 初始化为满牌状态
   893→        let wallState = { 1: 17, 2: 17, 3: 17, 4: 17 };
   894→
   895→        // 根据 drawInfo 确定抓牌起始位置
   896→        const drawInfo = this.gameState.drawInfo;
   897→        if (!drawInfo || !drawInfo.drawDirection) {
   898→            this.gameState.wallState = wallState;
   899→            return;
   900→        }
   901→
   902→        // 抓牌方向（逆时针，和 determineWildCard 一致）：东(1)→北(4)→西(3)→南(2)
   903→        // 这样才能和牌墙的物理布局对应
   904→        const directionOrder = [1, 4, 3, 2]; // 逆时针顺序
   905→        const drawDir = drawInfo.drawDirection;
   906→        const drawIdx = directionOrder.indexOf(drawDir);
   907→
   908→        // 计算起始方位之前跳过的牌墩数（被跳过的部分保持17墩）
   909→        const skipPiles = drawInfo.drawPile || 0;
   910→
   911→        // 计算已抓取的牌墩数（每墩2张）
   912→        const drawnPiles = Math.floor(drawnCards / 2);
   913→        const hasHalfPile = drawnCards % 2; // 是否有半墩（单张）
   914→
   915→        console.log(`更新牌墙: 已抓${drawnCards}张=${drawnPiles}墩+${hasHalfPile}张, 抓牌方位${drawDir}, 跳过${skipPiles}墩`);
   916→
   917→        // 从抓牌方位开始，逆时针方向抓牌
   918→        // 抓牌方位先抓完剩余的牌墩（17 - skipPiles）
   919→        let remainingPilesToDraw = drawnPiles;
   920→
   921→        // 首先处理抓牌方位
   922→        // 抓牌方位可抓的牌墩 = 17 - skipPiles（跳过的部分保持满）
   923→        const drawAvailablePiles = 17 - skipPiles;
   924→
   925→        if (remainingPilesToDraw > 0) {
   926→            if (remainingPilesToDraw >= drawAvailablePiles) {
   927→                // 抓牌方位抓完，剩余为跳过的牌墩数
   928→                wallState[drawDir] = skipPiles;
   929→                remainingPilesToDraw -= drawAvailablePiles;
   930→            } else {
   931→                // 抓牌方位还剩一些
   932→                wallState[drawDir] = skipPiles + (drawAvailablePiles - remainingPilesToDraw);
   933→                remainingPilesToDraw = 0;
   934→            }
   935→        }
   936→
   937→        // 然后逆时针处理其他方位
   938→        let currentDirIdx = (drawIdx + 1) % 4;
   939→        while (remainingPilesToDraw > 0 && currentDirIdx !== drawIdx) {
   940→            const currentDir = directionOrder[currentDirIdx];
   941→            if (remainingPilesToDraw >= 17) {
   942→                // 这个方位的牌墩全部抓完
   943→                wallState[currentDir] = 0;
   944→                remainingPilesToDraw -= 17;
   945→            } else {
   946→                // 这个方位还剩一些
   947→                wallState[currentDir] = 17 - remainingPilesToDraw;
   948→                remainingPilesToDraw = 0;
   949→            }
   950→            currentDirIdx = (currentDirIdx + 1) % 4;
   951→        }
   952→
   953→        this.gameState.wallState = wallState;
   954→        console.log(`牌墙状态更新: ${JSON.stringify(wallState)}`);
   955→    }
