   957→    // 出牌
   958→    playCard(playerId, cardId) {
   959→        const hand = this.gameState.hands[playerId];
   960→        if (!hand) return false;
   961→
   962→        const cardIndex = hand.findIndex(c => c.id === cardId);
   963→        if (cardIndex === -1) return false;
   964→
   965→        const card = hand.splice(cardIndex, 1)[0];
   966→
   967→        // 打出的牌背面朝上，加入弃牌堆
   968→        this.gameState.discardedPile.push({
   969→            playerId,
   970→            card,
   971→            hidden: true // 背面朝上
   972→        });
